      "id": "acoustic_gtr",
      "name": "Acoustic Guitar",
      "role": "Harmony / Rhythm",
      "register": {
        "low": 40,
        "high": 76
      },
      "instrument_hint": "acoustic guitar (steel-string, fingerpicked and strummed)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Sparse fingerpicked arpeggios outlining D major, with occasional open-string resonance",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Continue fingerpicking pattern with added passing tones; light strumming on phrase endings",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "Strummed open chords with rhythmic push, fuller voicings",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "Simplify to arpeggios to leave space for cello and counterline",
          "density": "sparse"
        },
        {
          "section_id": "bridge",
          "intent": "Arpeggiate B minor and related chords with a lower, contemplative voicing",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Strummed chords enriched with a high counter-melody on top",
          "density": "dense"
        }
      ]
    },
    {
      "id": "bass",
      "name": "Bass",
      "role": "Bass",
      "register": {
        "low": 28,
        "high": 52
      },
      "instrument_hint": "acoustic bass (or warm electric bass)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Long root notes with gentle decay",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Root-fifth motion with light passing tones",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "More active walking bass connecting chord changes",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "Adds occasional upper octave and fills in gaps",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Sustained notes, sometimes pedal on B, with slow stepwise movement",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Driving but smooth root-based line with syncopation",
          "density": "dense"
        }
      ]
    },
    {
      "id": "brush_drums",
      "name": "Brush Percussion",
      "role": "Pulse / Percussion",
      "register": {
        "low": 35,
        "high": 81
      },
      "instrument_hint": "brush kit (soft kick, snare with brushes, hi-hat, ride)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Only soft hi-hat on offbeats, barely present",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Brush snare on 2 and 4, light hi-hat eighths",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "Adds cross-stick and ride pattern, slightly more energy",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Similar to verse1 but with more ride instead of hi-hat",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Drops to shaker-like hi-hat and subtle cymbal swells",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Full brush pattern with snare on 2/4, ride, and occasional tom fills",
          "density": "dense"
        }
      ]
    },
    {
      "id": "cello",
      "name": "Cello",
      "role": "Sustained texture / countermelody",
      "register": {
        "low": 36,
        "high": 72
      },
      "instrument_hint": "cello (warm sustained lines and short motifs)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Long sustained tonic or fifth above guitar",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Short answering phrases, filling gaps after vocal (or implied vocal)",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "More present countermelody, harmonizing with main line",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Takes a more lead-like role, weaving around the guitar",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Main melodic voice in B minor, expressive but restrained",
          "density": "dense"
        },
        {
          "section_id": "final_chorus",
          "intent": "High sustained notes and countermelody, adding emotional lift",
          "density": "dense"
        }
      ]
    },
    {
      "id": "counterline",
      "name": "Subtle Counterline",
      "role": "Subtle melodic echo",
      "register": {
        "low": 55,
        "high": 84
      },
      "instrument_hint": "violin or soft synth lead (gentle, breathy)",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Tacet, enters later",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Occasional single-note echoes, filling space after phrases",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "More active, harmonizing with cello and guitar",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Alternates with cello, taking turns for melodic fills",
          "density": "medium"
        },
        {
          "section_id": "bridge",
          "intent": "Harmonizes with cello, sometimes in thirds",
          "density": "medium"
        },
        {
          "section_id": "final_chorus",
          "intent": "Adds a high obligato line, sparse but bright",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "warm_keys",
      "name": "Warm Keys",
      "role": "Harmonic pad / sparse chords",
      "register": {
        "low": 48,
        "high": 76
      },
      "instrument_hint": "warm electric piano or soft organ",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "Soft sustained chord, very quiet",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "Sparse chord stabs on offbeats or long tones",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "Adds fuller sustained chords, supporting guitar",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "Simpler, only sustaining root notes, leaving room",
          "density": "sparse"
        },
        {
          "section_id": "bridge",
          "intent": "Tacet or extremely subtle pad in B minor",
          "density": "sparse"
        },
        {
          "section_id": "final_chorus",
          "intent": "Adds a new sustained chord color, maybe with added 9th",
          "density": "medium"
        }
      ]
    }
  ],
  "motif_strategy": "Main motif is a four-note rising phrase first heard in intro guitar, later echoed by cello and counterline; bridge develops it in minor, final chorus extends it with a leap.",
  "harmony_strategy": "Diatonic I-V-vi-IV progressions with occasional ii; bridge moves to relative minor (B minor) with iv-VII-III-VI; final chorus returns to D with added color tones (sus2, add9).",
  "groove_strategy": "Brush percussion evolves from offbeat hi-hat to full brush pattern; bass and guitar interlock with eighth-note syncopation in chorus, while verses stay more straight-ahead; bridge uses rubato feel with minimal percussive pulse."
}
